mapper.select:
  	SELECT stat_time,port,sum(sum) as sum from traffic_port_active_statistic
	WHERE  port in (${port}) and stat_time >= #{statStartTime} and stat_time < #{statEndTime} 
	
	GROUP BY stat_time,port ORDER BY stat_time ASC

SELECT port,sum(sum) as sum from traffic_port_active_statistic WHERE
stat_time >= #{statStartTime} and stat_time < #{statEndTime}
GROUP BY port order by sum desc LIMIT 0,10
